package com.yeshj.pacman.model;




public class TaskModel implements Serializable {

    private static final long serialVersionUID = -1759501103L;
    private Integer     tid;
    private Integer     cid;
    private Integer     lid;
    private String      file;
    private Timestamp   begin;
    private Timestamp   end;
    private Integer     type;
    private Integer     status;
    private String      err;
    private String      guid;
    private boolean     free;

    public TaskModel() {
        super();
    }

    public TaskModel(
        Integer tid, 
        Integer cid, 
        Integer lid,
        String guid,
        String  file,
        Timestamp begin, 
        Timestamp end, 
        Integer type, 
        Integer status, 
        String err,
        boolean free) {

        super();
        this.tid = tid;
        this.cid = cid;
        this.lid = lid;
        this.file = file;
        this.begin = begin;
        this.end = end;
        this.type = type;
        this.status = status;
        this.err = err;
        this.guid = guid;
        this.free = free;
    }

    public Integer getTid() {
        return this.tid;
    }

    public void setTid(Integer tid) {
        this.tid = tid;
    }

    public Integer getCid() {
        return this.cid;
    }

    public void setCid(Integer cid) {
        this.cid = cid;
    }

    public Integer getLid() {
        return this.lid;
    }

    public void setLid(Integer lid) {
        this.lid = lid;
    }

    public Timestamp getBegin() {
        return this.begin;
    }

    public void setBegin(Timestamp begin) {
        this.begin = begin;
    }

    public Timestamp getEnd() {
        return this.end;
    }

    public void setEnd(Timestamp end) {
        this.end = end;
    }

    public Integer getType() {
        return this.type;
    }

    public void setType(Integer type) {
        this.type = type;
    }

    public Integer getStatus() {
        return this.status;
    }

    public void setStatus(Integer status) {
        this.status = status;
    }

    public String getErr() {
        return this.err;
    }

    public void setErr(String err) {
        this.err = err;
    }

    public String getFile() {
        return file;
    }

    public void setFile(String file) {
        this.file = file;
    }

    @Override
    public boolean equals(Object otherObject) {
        if (this == otherObject) return true;
        if (otherObject == null) return false;
        if (this.getClass() != otherObject.getClass()) return false;
        TaskModel other = (TaskModel) otherObject;
        return this.tid.equals(other.tid)
            && this.cid.equals(other.cid)
            && this.lid.equals(other.lid)
            && this.begin.equals(other.begin)
            && this.end.equals(other.end)
            && this.type.equals(other.type)
            && this.status.equals(other.status)
            && this.err.equals(other.err);
    }

    @Override
    public int hashCode() {
        int hash = 0;
        hash += (this.tid != null ? this.tid.hashCode() : 0);
        hash += (this.cid != null ? this.cid.hashCode() : 0);
        hash += (this.lid != null ? this.lid.hashCode() : 0);
        hash += (this.file != null ? this.file.hashCode() : 0);
        hash += (this.begin != null ? this.begin.hashCode() : 0);
        hash += (this.end != null ? this.end.hashCode() : 0);
        hash += (this.type != null ? this.type.hashCode() : 0);
        hash += (this.status != null ? this.status.hashCode() : 0);
        hash += (this.err != null ? this.err.hashCode() : 0);
        return hash;
    }

    @Override
    public String toString() {
        String content = "";
        content += "[ tid = " + this.tid;
        content += ", cid = " + this.cid;
        content += ", lid = " + this.lid;
        content += ", file = " + this.file;
        content += ", begin = " + this.begin;
        content += ", end = " + this.end;
        content += ", type = " + this.type;
        content += ", status = " + this.status;
        content += ", err = " + this.err + " ]";
        return content;
    }

    public String getGuid() {
        return guid;
    }

    public void setGuid(String guid) {
        this.guid = guid;
    }

    public boolean isFree() {
        return free;
    }

    public void setFree(boolean free) {
        this.free = free;
    }

