    @Override
    public void init() throws ServletException{
        String err = null;
        logger.info("åå§åServletä»£çç±»...");
        String targetServletBean = this.getInitParameter("targetServletBean");
        if(targetServletBean == null || targetServletBean.trim().isEmpty()){
