        if(this.proxy == null){
            logger.error(err = "è£è½½[servlet:" + targetServletBean + "]å¤±è´¥ï¼æªå¨Springéç½®ä¸­æ¾å°å¯¹è±¡ï¼");
            throw new ServletException(err);
