        this.proxy.init(this.getServletConfig());
        logger.info("æåè£è½½[servlet:" + targetServletBean + "]å¯¹è±¡:[" + this.proxy.getClass().getName() + "]");
        logger.info("åå§åServletä»£çç±»å®æã");
    }

    @Override
