@Controller
public class LhjController {

    @Autowired
    private MaterialBrandService materialBrandService;

    @RequestMapping(value="getLhjMaterialBrands.ajax")
    @ResponseBody
    public String getLhjMaterialBrands(Locale locale, Model model, ModelMap modelMap,
            HttpServletRequest request, HttpServletResponse response){
        response.setCharacterEncoding("UTF-8");
        String json = "{\"data\":[";    MaterialBrand[] mbs = materialBrandService.queryMaterialBrandsByType("lhj");
        for (MaterialBrand mb : mbs) {
            String str = "{" +
                    "\"name\":\"" + mb.getName() +"\"" +
                    ",\"id\":\"" + mb.getID() + "\"" +
                    ",\"py\":\"" + mb.getPy() + "\"" +
                    "},";
            json += str;
        }
        json = json.substring(0, json.length()-1);  json += "]}";   try {
            response.getWriter().write(json);} catch (Exception e) {
            e.printStackTrace();
        }

        return null;
    }
}
