package com.nercis.isscp.idl;






public enum CheckResultStatus implements org.apache.thrift.TEnum {
  received(0),
  nonexec(1),
  executing(2),
  executed(3),
  timeout(4),
  failure(5),
  breaked(6),
  other(7);

  private final int value;

  private CheckResultStatus(int value) {
    this.value = value;
  }

  public int getValue() {
    return value;
  }

  public static CheckResultStatus findByValue(int value) { 
    switch (value) {
      case 0:
        return received;
      case 1:
        return nonexec;
      case 2:
        return executing;
      case 3:
        return executed;
      case 4:
        return timeout;
      case 5:
        return failure;
      case 6:
        return breaked;
      case 7:
        return other;
      default:
        return null;
    }
  }
}
