package com.nercis.isscp.engine;






public enum EngineOperation implements org.apache.thrift.TEnum {
  shutdown(1),
  restart(2),
  startup(3),
  sleep(4);

  private final int value;

  private EngineOperation(int value) {
    this.value = value;
  }

  public int getValue() {
    return value;
  }

  public static EngineOperation findByValue(int value) { 
    switch (value) {
      case 1:
        return shutdown;
      case 2:
        return restart;
      case 3:
        return startup;
      case 4:
        return sleep;
      default:
        return null;
    }
  }
}
