        super(pCellX, pCellY, CELL_WIDTH, 2 * CELL_HEIGHT, pTiledTextureRegion, pVertexBufferObjectManager);

        this.setRotationCenterY(CELL_HEIGHT / 2);
    }

    public void setRotation(final Direction pDirection) {
        switch(pDirection) {
            case UP:
                this.setRotation(180);
                break;
            case DOWN:
                this.setRotation(0);
                break;
            case LEFT:
                this.setRotation(90);
