public class MeetableLayer extends Layer{

    private static final long serialVersionUID = 1265133035026861860L;
    private MyMeetableDrawable[][] mapMatrixMeetable;private MyMeetableDrawable[][] mapMatrixForMeetable;public MeetableLayer(){}

    public MeetableLayer(Resources resources) {
        super(resources);

        this.mapMatrixMeetable = GameData2.mapData;
        initMapMatrixForMeetable();
    }

    public MyDrawable[][] getMapMatrix()
    {
        return mapMatrixMeetable;
    }

    public void initMapMatrixForMeetable(){mapMatrixForMeetable = new MyMeetableDrawable[40][60]; 
        for(int i=0; i<mapMatrixMeetable.length; i++){
            for(int j=0; j<mapMatrixMeetable[i].length; j++){
                if(mapMatrixMeetable[i][j] != null){
                    int x = mapMatrixMeetable[i][j].col - mapMatrixMeetable[i][j].refCol;
                    int y = mapMatrixMeetable[i][j].row + mapMatrixMeetable[i][j].refRow;
                    int[][] meetableMatrix = mapMatrixMeetable[i][j].meetableMatrix;
                    for(int k=0; k<meetableMatrix.length; k++){
                        mapMatrixForMeetable[y-meetableMatrix[k][1]][x+meetableMatrix[k][0]] = mapMatrixMeetable[i][j];
                    }                   
                }
            }
        }
    }

    public MyMeetableDrawable check(Hero hero){int col = hero.col;int row = hero.row;switch(hero.direction%4){case 0:if(mapMatrixForMeetable[row][col-1] != null){return mapMatrixForMeetable[row][col-1];
            }
            else if(mapMatrixForMeetable[row][col+1] != null){return mapMatrixForMeetable[row][col+1];
            }
            break;
        case 1:if(mapMatrixForMeetable[row-1][col] != null){return mapMatrixForMeetable[row-1][col];
            }
            else if(mapMatrixForMeetable[row+1][col] != null){return mapMatrixForMeetable[row+1][col];
            }
            break;
        case 2:if(mapMatrixForMeetable[row-1][col] != null){return mapMatrixForMeetable[row-1][col];
            }
            else if(mapMatrixForMeetable[row+1][col] != null){return mapMatrixForMeetable[row+1][col];
            }
            break;
        case 3:if(mapMatrixForMeetable[row][col-1] != null){return mapMatrixForMeetable[row][col-1];
            }
            else if(mapMatrixForMeetable[row][col+1] != null){return mapMatrixForMeetable[row][col+1];
            }
            break;
        }
        return null;
    }
