package cn.itcast_02;




public class VectorDemo {
    public static void main(String[] args) {
        Vector v = new Vector();

        v.addElement("hello");
        v.addElement("world");
        v.addElement("java");

        Enumeration en = v.elements();
        while (en.hasMoreElements()) {
            String s = (String) en.nextElement();
            System.out.println(s);
        }

        System.out.println("v:" + v);
    }
}
